            "argName": "header_value",
            "argValue": "gzip"
        }, {
            "argName": "duplicate",
            "argValue": "off"
        }],
        "functionName": "origin_request_header"
}]

```

使用parentId的情况下，配置示例如下： 使用函数origin_request_header添加回源HTTP请求头的时候引用了configid=222728944812032的规则条件，请求参数如下：

```
        "functionArgs": [{
            "argName": "header_operation_type",
